package cz.mh.rallye.rallye_backend.competition;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import cz.mh.rallye.rallye_backend.competition.domain.*;import cz.mh.rallye.rallye_backend.templates.domain.StageConfiguration;import static cz.mh.rallye.rallye_backend.competition.domain.RaceEvaluator.*;
class RaceEvaluatorTest {
 final RaceEvaluator engine=new RaceEvaluator();final Instant at=Instant.parse("2026-10-29T10:00:00Z");final UUID id=UUID.randomUUID();
 Definition def(boolean gps,boolean code,Long wrong,long rate,long minimum,long early){return new Definition(2,3,List.of(new Stage(id,id,1,"A",0L,10L,"Text",new StageConfiguration(new StageConfiguration.Gps(gps,50d,14d,100d,4L,5L),new StageConfiguration.Code(code,"YES",wrong),new StageConfiguration.TimePenalty(true,60000L,rate),new StageConfiguration.Delayed(true,minimum,early)))));}
 State act(Definition d,State s,String type,String code){return engine.evaluate(d,s,type,id,code,UUID.randomUUID(),1);}
 @Test void codeTimeAndEarlyAreExactAndDeterministic(){for(long ms:new long[]{0,60000,60001,125000}){var d=def(false,true,null,3,900000,2);var state=engine.shift(engine.start(d,at),ms,UUID.randomUUID(),1);UUID command=UUID.randomUUID();var result=engine.evaluate(d,state,"CODE",id," yes ",command,2);long expected=(ms/60000+(ms%60000==0?0:1))*3+((900000-ms)/1000+((900000-ms)%1000==0?0:1))*2;assertEquals(expected,total(result));assertEquals("COMPLETED",result.status());assertEquals(result,engine.evaluate(d,state,"CODE",id,"YES",command,2));}}
 @Test void andWorksInBothOrdersAndDoesNotReevaluateSatisfiedChecks(){var d=def(true,true,null,0,0,0);for(boolean codeFirst:new boolean[]{true,false}){var state=engine.position(engine.start(d,at),new Position(50,14,0,false),UUID.randomUUID(),1);state=act(d,state,codeFirst?"CODE":"GPS","YES");assertEquals("RUNNING",state.status());state=act(d,state,codeFirst?"CODE":"GPS","WRONG");assertEquals("CHECK_ALREADY_SATISFIED",state.lastAction().outcome());assertEquals(0,total(state));state=act(d,state,codeFirst?"GPS":"CODE","YES");assertEquals("COMPLETED",state.status());}}
 @Test void gpsTechnicalErrorsSpoofAndBoundary(){var d=def(true,false,null,0,0,0);var s=engine.start(d,at);assertEquals("GPS_UNAVAILABLE",act(d,s,"GPS",null).lastAction().outcome());s=engine.position(s,new Position(50,14,101,false),UUID.randomUUID(),1);assertEquals(0,total(act(d,s,"GPS",null)));s=engine.position(s,new Position(50,14,0,true),UUID.randomUUID(),2);assertEquals(5,total(act(d,s,"GPS",null)));s=engine.position(s,GpsMath.outside(50,14,100),UUID.randomUUID(),3);assertEquals(4,total(act(d,s,"GPS",null)));s=engine.position(s,new Position(50,14,100,false),UUID.randomUUID(),4);assertEquals("COMPLETED",act(d,s,"GPS",null).status());}
 @Test void skipReplacesSignedHistoryAndDelta(){for(Long override:new Long[]{null,0L,-4L}){var d=def(false,true,override,0,0,0);var s=act(d,engine.start(d,at),"CODE","WRONG");long previous=override==null?3:override;assertEquals(previous,total(s));s=act(d,s,"SKIP",null);assertEquals(12,total(s));assertEquals(12-previous,s.lastAction().pointsDelta());assertFalse(s.penalties().getFirst().effective());assertNotNull(s.penalties().getFirst().supersededBy());assertEquals("COMPLETED",s.status());}}
 @Test void clockBackIsNotUndoAndFloorBlocksBusinessActions(){var d=def(false,true,null,0,0,0);var s=engine.shift(engine.start(d,at),120000,UUID.randomUUID(),1);s=act(d,s,"CODE","WRONG");s=engine.shift(s,-60000,UUID.randomUUID(),3);assertEquals(3,total(s));var past=s;assertEquals("SIMULATION_CLOCK_BEFORE_STATE",assertThrows(RuleViolation.class,()->act(d,past,"CODE","YES")).code());s=engine.shift(s,60000,UUID.randomUUID(),4);s=act(d,s,"CODE","YES");var completed=engine.shift(s,-60000,UUID.randomUUID(),5);assertEquals("COMPLETED",completed.status());assertEquals(s.penalties(),completed.penalties());assertThrows(RuleViolation.class,()->engine.shift(completed,-60001,UUID.randomUUID(),6));}
 @Test void overflowDoesNotMutateInput(){var d=def(false,true,null,Long.MAX_VALUE,0,0);var s=engine.shift(engine.start(d,at),60001,UUID.randomUUID(),1);assertEquals("SIMULATION_POINTS_OVERFLOW",assertThrows(RuleViolation.class,()->act(d,s,"CODE","YES")).code());assertEquals(0,total(s));assertEquals("RUNNING",s.status());}
 @Test void gpsGeometryHandlesDatelineAndPoles(){assertTrue(GpsMath.distance(0,179.999,0,-179.999)<300);assertEquals(0,GpsMath.distance(90,0,90,180),1e-6);assertThrows(RuleViolation.class,()->GpsMath.outside(0,0,Math.PI*GpsMath.EARTH_RADIUS));}
 @Test void verifiedFactsReplayWithoutCodeAndDoNotDoublePenalties(){var d=def(false,true,null,3,900000,2);var initial=engine.start(d,at);var wrong=act(d,initial,"CODE","NO");assertEquals(wrong,engine.replay(d,initial,wrong.lastAction()));var skipped=act(d,wrong,"SKIP",null);assertEquals(skipped,engine.replay(d,wrong,skipped.lastAction()));assertEquals(12,total(skipped));assertEquals(0,total(initial));}
 @Test void successfulPartialCheckSurvivesClockAndPositionAndReplay(){var d=def(true,true,null,0,0,0);var s=engine.start(d,at);s=act(d,s,"CODE","YES");Instant floor=s.timeFloor();s=engine.shift(s,10000,UUID.randomUUID(),2);var repeated=act(d,s,"CODE","WRONG");assertEquals(floor,repeated.timeFloor());assertEquals(0,total(repeated));assertTrue(repeated.stages().getFirst().codeSatisfied());assertEquals(repeated,engine.replay(d,s,repeated.lastAction()));}
 @Test void activationOfNextStageAndNullMaximumDoNotCarryChecks(){var d=def(false,true,null,0,0,0);var first=d.stages().getFirst();UUID second=UUID.randomUUID();d=new Definition(-2,3,List.of(first,new Stage(second,second,2,"B",0L,null,"Text",first.configuration())));var s=engine.start(d,at);s=act(d,s,"CODE","YES");assertEquals("RUNNING",s.status());assertEquals(second,current(s).stageId());assertFalse(current(s).codeSatisfied());s=engine.evaluate(d,s,"SKIP",second,null,UUID.randomUUID(),2);assertEquals("COMPLETED",s.status());assertEquals(-2,total(s));assertEquals("SKIPPED",s.stages().getLast().status());}

 @Test void organizerEndReplacesOnlyUnfinishedStagesAndKeepsDistinctPenaltyIds(){
  var base=def(false,true,3L,0,0,0).stages().getFirst();var stages=new ArrayList<Stage>();
  for(int n=0;n<3;n++){UUID stage=UUID.randomUUID();stages.add(new Stage(stage,stage,n+1,"S"+n,0L,(long)n,"Text",base.configuration()));}
  var d=new Definition(-2,3,stages);var state=engine.start(d,at);
  state=engine.evaluate(d,state,"SKIP",stages.getFirst().id(),null,UUID.randomUUID(),1);
  state=engine.evaluate(d,state,"CODE",stages.get(1).id(),"wrong",UUID.randomUUID(),2);
  UUID action=UUID.randomUUID();var ended=engine.endRace(d,state,action,3);
  assertEquals(-3,total(ended)); // skipped -2, unfinished -1 and 0; replaces previous +3.
  assertEquals(List.of("SKIPPED","ENDED","ENDED"),ended.stages().stream().map(Progress::status).toList());
  assertNull(ended.stages().get(1).completedAt());assertEquals(at,ended.stages().get(1).endedAt());assertNull(ended.stages().get(2).activatedAt());
  var replacements=ended.penalties().stream().filter(p->p.actionId().equals(action)).toList();assertEquals(2,replacements.size());assertNotEquals(replacements.getFirst().id(),replacements.getLast().id());
  assertFalse(ended.penalties().stream().filter(p->p.cause().equals("WRONG_CODE")).findFirst().orElseThrow().effective());
  assertEquals(ended,engine.endRace(d,state,action,3));
 }
 @Test void actualStartResetsStageMeasurementAndEndPreservesCompletedTime(){
  var d=def(false,true,0L,3,0,0);var waiting=engine.waiting(d,at);var later=engine.shift(waiting,120000,UUID.randomUUID(),1);
  var started=engine.startRace(later,UUID.randomUUID(),2);assertEquals(later.virtualNow(),current(started).activatedAt());
  var done=engine.evaluate(d,started,"CODE",id,"YES",UUID.randomUUID(),3);assertEquals(0,total(done));
  var ended=engine.endRace(d,done,UUID.randomUUID(),4);assertEquals("COMPLETED",ended.status());assertEquals(done.stages(),ended.stages());assertEquals(0,total(ended));
 }
}
